import subprocess, re

def run(args):
    return subprocess.run(args, capture_output=True, text=True).stdout

files = [f for f in run(["git","ls-tree","-r","--name-only","origin/main","--","S01","S02","S03"]).split() if f.endswith(".md")]
cache={}
def body(sha):
    if sha not in cache: cache[sha]=run(["git","show","-s","--format=%B",sha])
    return cache[sha].replace("\r\n","\n")

def utterance(sha):
    lines=body(sha).split("\n")
    idx=[k for k,l in enumerate(lines) if l.startswith("Reply-To:")]
    if not idx: return None
    i=idx[0]+1
    while i<len(lines) and lines[i].strip()=="": i+=1
    return "\n".join(lines[i:]).strip("\n")

problems=[]; entries=0
for f in sorted(files):
    text=run(["git","show",f"origin/main:{f}"]).replace("\r\n","\n")
    lines=text.split("\n")
