    for n,k in enumerate(src_idx):
        m=re.match(r"Source: friend/(\w+) @ ([0-9a-f]{40})", lines[k])
        if not m: problems.append((f,k+1,"unparsed")); continue
        spk,sha=m.group(1),m.group(2)
        end=src_idx[n+1] if n+1<len(src_idx) else len(lines)
        # cut trailing header lines of next entry (**Name** (ts))
        block=lines[k+1:end]
        while block and block[-1].strip()=="": block.pop()
        while block and (block[-1].startswith("**") or block[-1].strip()=="" ): block.pop()
        while block and block[0].strip()=="": block.pop(0)
        recorded="\n".join(block).strip("\n")
        src=utterance(sha) or ""
        entries+=1
        if recorded.strip()!=src.strip():
            problems.append((f,k+1,f"{spk} {sha[:8]}","REC: "+recorded.strip()[:120]+"  || SRC: "+src.strip()[:120]))
print("entries:",entries,"mismatches:",len(problems))
for p in problems[:20]:
    print("---",p[0],"line",p[1],p[2]); print("   ",p[3])
