import subprocess, re, difflib

def run(a): return subprocess.run(a,capture_output=True,text=True).stdout
files=[f for f in run(["git","ls-tree","-r","--name-only","origin/main","--","S01","S02","S03"]).split() if f.endswith(".md")]
cache={}
def body(sha):
    if sha not in cache: cache[sha]=run(["git","show","-s","--format=%B",sha]).replace("\r\n","\n")
    return cache[sha]
def utterance(sha):
    lines=body(sha).split("\n")
    idx=[k for k,l in enumerate(lines) if l.startswith("Reply-To:")]
    if not idx: return None
    i=idx[0]+1
    while i<len(lines) and lines[i].strip()=="": i+=1
    return "\n".join(lines[i:]).strip("\n")
real=[]
for f in sorted(files):
    lines=run(["git","show",f"origin/main:{f}"]).replace("\r\n","\n").split("\n")
    src_idx=[k for k,l in enumerate(lines) if l.startswith("Source: friend/")]
    for n,k in enumerate(src_idx):
        m=re.match(r"Source: friend/(\w+) @ ([0-9a-f]{40})", lines[k])
        spk,sha=m.group(1),m.group(2)
        end=src_idx[n+1] if n+1<len(src_idx) else len(lines)
        block=lines[k+1:end]
        while block and block[-1].strip()=="": block.pop()
        while block and block[-1].startswith("**"): block.pop()
        while block and block[0].strip()=="": block.pop(0)
        recorded="\n".join(block).strip("\n")
        src=utterance(sha) or ""
        if recorded.strip()!=src.strip():
            sm=difflib.SequenceMatcher(None,src.strip().split(),recorded.strip().split())
            ops=[o for o in sm.get_opcodes() if o[0]!='equal']
            srcw=src.split(); recw=recorded.split()
            det=[]
            for tag,i1,i2,j1,j2 in ops[:4]:
                det.append(f"{tag}: SRC[{i1}:{i2}]={' '.join(srcw[i1:i2])[:110]!r} REC[{j1}:{j2}]={' '.join(recw[j1:j2])[:110]!r}")
            real.append((f,spk,sha[:8],det))
print("mismatching entries:",len(real))
for f,spk,sh,det in real:
    print(f"--- {f} {spk} {sh}")
    for d in det: print("    ",d)
