import subprocess, re
def run(a): return subprocess.run(a,capture_output=True,text=True)
files=[f for f in run(["git","ls-tree","-r","--name-only","origin/main","--","S01","S02","S03"]).stdout.split() if f.endswith(".md")]
bad=[]; total=0
seen={}
for f in sorted(files):
    txt=run(["git","show",f"origin/main:{f}"]).stdout
    for line in txt.split("\n"):
        if line.startswith("Source:"):
            total+=1
            m=re.match(r"Source: friend/(\w+) @ ([0-9a-f]{40})$", line.strip())
            if not m:
                bad.append((f,"malformed",line)); continue
            spk,sha=m.groups()
            r=run(["git","cat-file","-e",sha+"^{commit}"])
            if r.returncode!=0:
                bad.append((f,"missing commit",line)); continue
            body=run(["git","show","-s","--format=%B",sha]).stdout
            mspk=re.search(r"^Speaker:\s*(\w+)",body,re.M)
            # also check which refs contain it
            has=run(["git","branch","-a","--contains",sha]).stdout
            seen.setdefault(sha,[]).append(f)
            if mspk and mspk.group(1).lower()!=spk:
                bad.append((f,f"speaker mismatch: line={spk} body={mspk.group(1)}",sha))
print("total Source lines:",total)
print("problems:",len(bad))
for b in bad[:20]: print("  ",b)
dups={k:v for k,v in seen.items() if len(v)>1}
print("source shas used more than once:",len(dups))
for k,v in list(dups.items())[:10]: print("  ",k[:8],v)
