import subprocess, re
def run(a): return subprocess.run(a,capture_output=True,text=True).stdout
msgs=set()
for b in ["ross","monica","rachel","joey","chandler","phoebe"]:
    for sha in run(["git","log","origin/friend/"+b,"--format=%H"]).split():
        body=run(["git","show","-s","--format=%B",sha])
        if re.search(r"^Friend-Message:\s*1\s*$",body,re.M):
            msgs.add(sha)
srcs=set()
for f in [x for x in run(["git","ls-tree","-r","--name-only","origin/main","--","S01","S02","S03"]).split() if x.endswith(".md")]:
    for line in run(["git","show",f"origin/main:{f}"]).split("\n"):
        m=re.match(r"Source: friend/\w+ @ ([0-9a-f]{40})$",line.strip())
        if m: srcs.add(m.group(1))
print("Friend-Message commits:",len(msgs))
print("distinct transcript sources:",len(srcs))
print("messages not in transcript:",len(msgs-srcs))
for s in sorted(msgs-srcs):
    print("  MISSING",s, run(["git","log","-1","--format=%cI %s",s]).strip())
print("transcript sources that are not Friend-Message commits:",len(srcs-msgs))
for s in sorted(srcs-msgs):
    print("  EXTRA",s, run(["git","log","-1","--format=%cI %s",s]).strip())
